@using sv_c3a154f542654cf5a218dabcd4ccdb88.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State

<select class="form-select form-select-sm w-auto"
        value="@State.CurrentWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in _warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private readonly record struct Warehouse(string Id, string Name);

    private static readonly Warehouse[] _warehouses =
    [
        new("WH-001", "Warehouse A"),
        new("WH-002", "Warehouse B"),
        new("WH-003", "Warehouse C"),
        new("WH-004", "Warehouse D"),
    ];

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        State.CurrentWarehouseId = e.Value?.ToString() ?? _warehouses[0].Id;
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_c3a154f542654cf5a218dabcd4ccdb88.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State

<span class="badge bg-danger rounded-pill ms-2">@State.LowStockAlertCount</span>

@code {
    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= OnStateChanged;
    }
}

