@using sv_c3a154f542654cf5a218dabcd4ccdb88.Services
@implements IDisposable
@inject WarehouseStateService State
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Warehouse: <strong>@State.CurrentWarehouseId</strong>
        </p>
        <p class="card-text">
            Items below minimum level:
            <span class="badge bg-warning text-dark fs-5">@State.LowStockAlertCount</span>
        </p>
        <p class="text-muted small mb-0">Polling every 10 seconds</p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await RefreshAlertCount();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(10), ct).ConfigureAwait(false);
            if (ct.IsCancellationRequested) break;
            await InvokeAsync(async () =>
            {
                await RefreshAlertCount();
                StateHasChanged();
            });
        }
    }

    private async Task RefreshAlertCount()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        // Setting this property notifies ALL subscribers (including the sidebar badge).
        State.LowStockAlertCount = count;
    }

    private async void OnWarehouseChanged()
    {
        // Warehouse changed — immediately fetch new counts.
        await InvokeAsync(async () =>
        {
            await RefreshAlertCount();
            StateHasChanged();
        });
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

